// src/pages/SubscienceUnit.js
import React, { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import Sidebar from "../components/Sidebar";

function SubscienceUnit() {
  const { subId } = useParams();
  const navigate = useNavigate();
  const user = JSON.parse(localStorage.getItem("user"));

  const [lessons, setLessons] = useState([]);
  const [tutorsMap, setTutorsMap] = useState({});
  const [sessionsMap, setSessionsMap] = useState({});
  const [loading, setLoading] = useState(true);
  const [unitName, setUnitName] = useState("");
  const [processingSignup, setProcessingSignup] = useState(null);

  useEffect(() => {
    async function fetchLessons() {
      try {
        const res = await fetch(
          `http://localhost:8080/subsciences/${subId}/lessons/${user.id}`
        );
        const data = await res.json();

        setLessons(data.lessons || []);
        setUnitName(data.lessons?.[0]?.subscienceName || "Unit");
        // fetch tutors and sessions for lessons
        const lessonIds = (data.lessons || []).map((l) => l.id);
        if (lessonIds.length) {
          const tutorsFetches = lessonIds.map((lid) =>
            fetch(`http://localhost:8080/lessons/${lid}/tutors`).then((r) => r.json()).catch(() => ({ tutors: [] }))
          );

          const sessionsFetches = lessonIds.map((lid) =>
            fetch(`http://localhost:8080/lessons/${lid}/sessions`).then((r) => r.json()).catch(() => ({ sessions: [] }))
          );

          const tutorsResults = await Promise.all(tutorsFetches);
          const sessionsResults = await Promise.all(sessionsFetches);

          const tMap = {};
          lessonIds.forEach((id, idx) => {
            tMap[id] = tutorsResults[idx].tutors || [];
          });
          setTutorsMap(tMap);

          const sMap = {};
          lessonIds.forEach((id, idx) => {
            sMap[id] = sessionsResults[idx].sessions || [];
          });
          setSessionsMap(sMap);
        }
        setLoading(false);
      } catch (err) {
        console.error("Subscience lessons error:", err);
        setLoading(false);
      }
    }

    fetchLessons();
  }, [subId, user.id]);

  async function signupToSession(session) {
    if (!user) return alert("Please log in to sign up.");
    if (processingSignup) return;

    const confirmMsg = `Join session with ${session.tutor_name} on ${new Date(session.session_time).toLocaleString()}?`;
    if (!window.confirm(confirmMsg)) return;

    setProcessingSignup(session.id);
    try {
      const res = await fetch(`http://localhost:8080/session_signups`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ session_id: session.id, user_id: user.id }),
      });

      const data = await res.json();
      if (!res.ok) throw new Error(data.message || "Signup failed");

      alert(data.message || "Signed up for session");

      // optimistic update: reduce available spots locally
      setSessionsMap((prev) => {
        const copy = { ...prev };
        if (!copy[session.lesson_id]) return prev;
        copy[session.lesson_id] = copy[session.lesson_id].map((s) =>
          s.id === session.id ? { ...s, spots_filled: (s.spots_filled || 0) + 1 } : s
        );
        return copy;
      });
    } catch (err) {
      console.error("Signup error:", err);
      alert(err.message || "Could not sign up");
    } finally {
      setProcessingSignup(null);
    }
  }

  if (!user) {
    return <h1 style={{ color: "white" }}>Please log in</h1>;
  }

  const totalLessons = lessons.length;
  const completedCount = lessons.filter((l) => l.status === "completed").length;
  const progressPercent =
    totalLessons === 0 ? 0 : Math.round((completedCount / totalLessons) * 100);

  const allLessonsCompleted = completedCount === 10;

  return (
    <div className="dashboard-page">
      <Sidebar />

      <main className="dashboard-main">
        <header className="dashboard-header">
          <div>
            <h1>{unitName} Unit</h1>
            <p className="dashboard-subtitle">
              Complete lessons, play games, ask questions, and finish the Unit Test.
            </p>
          </div>

          <div className="dashboard-header-actions">
            <button
              className="primary-btn"
              onClick={() => navigate(`/qna/${subId}`)}
            >
              Q & A
            </button>

            <button
              className="ghost-btn"
              onClick={() => navigate(`/games/${subId}`)}
            >
              Games
            </button>
          </div>
        </header>

        {loading ? (
          <p className="dashboard-loading">Loading lessons...</p>
        ) : (
          <div className="subscience-layout">
            {/* Progress */}
            <section className="dashboard-panel subscience-progress-panel">
              <h2>Unit Progress</h2>
              <p className="subscience-progress-text">
                {completedCount} of 10 lessons completed
              </p>
              <div className="subscience-progress-bar">
                <div
                  className="subscience-progress-fill"
                  style={{ width: `${progressPercent}%` }}
                />
              </div>
              <p className="subscience-progress-percent">{progressPercent}% complete</p>
            </section>

            {/* Lessons */}
            <section className="dashboard-panel subscience-lessons-panel">
              <h2>Lessons</h2>
              <ul className="subscience-lessons-list">
                {lessons.map((lesson) => (
                  <li key={lesson.id} className={`subscience-lesson ${lesson.status}`}>
                    <div className="subscience-lesson-main">
                      <div>
                        <p className="subscience-lesson-number">
                          Lesson {lesson.lesson_number}
                        </p>
                        <p className="subscience-lesson-title">{lesson.title}</p>
                        <p className="subscience-lesson-status">
                          Status: {lesson.status}
                        </p>
                      </div>

                      <div className="subscience-lesson-tags">
                        {lesson.status === "completed" && (
                          <span className="tag tag-completed">Completed</span>
                        )}
                        {lesson.status === "unlocked" && (
                          <span className="tag tag-unlocked">Ready</span>
                        )}
                        {lesson.status === "locked" && (
                          <span className="tag tag-locked">Locked</span>
                        )}
                      </div>
                    </div>

                    <div className="subscience-lesson-actions">
                      <button
                        className="lesson-action-btn"
                        disabled={lesson.status === "locked"}
                        onClick={() =>
                          navigate(`/lesson/${lesson.id}`, {
                            state: { lesson, subId },
                          })
                        }
                      >
                        View Lesson
                      </button>
                    </div>
                    {/* Tutors and Sessions for this lesson */}
                    <div className="subscience-lesson-extra">
                      <div className="lesson-tutors">
                        <h4>Tutors</h4>
                        {(tutorsMap[lesson.id] || []).length === 0 ? (
                          <p className="small muted">No tutors listed</p>
                        ) : (
                          <ul>
                            {(tutorsMap[lesson.id] || []).map((t) => (
                              <li key={t.id} className="tutor-item">
                                <strong>{t.name}</strong>
                                <div className="tutor-bio">{t.bio}</div>
                              </li>
                            ))}
                          </ul>
                        )}
                      </div>

                      <div className="lesson-sessions">
                        <h4>Upcoming Sessions</h4>
                        {(sessionsMap[lesson.id] || []).length === 0 ? (
                          <p className="small muted">No sessions scheduled</p>
                        ) : (
                          <ul>
                            {(sessionsMap[lesson.id] || []).map((s) => {
                              const spotsFilled = s.spots_filled || 0;
                              const max = s.max_spots || 7;
                              const spotsLeft = Math.max(0, max - spotsFilled);

                              return (
                                <li key={s.id} className="session-item">
                                  <div>
                                    <p className="session-time">{new Date(s.session_time).toLocaleString()}</p>
                                    <p className="session-tutor">Tutor: {s.tutor_name}</p>
                                    <p className="session-spots">{spotsLeft} spots left</p>
                                  </div>
                                  <div>
                                    <button
                                      className="secondary-btn"
                                      disabled={spotsLeft === 0 || processingSignup === s.id}
                                      onClick={() => signupToSession(s)}
                                    >
                                      {processingSignup === s.id ? "Signing up..." : "Join"}
                                    </button>
                                  </div>
                                </li>
                              );
                            })}
                          </ul>
                        )}
                      </div>
                    </div>
                  </li>
                ))}

                {/* UNIT TEST */}
                <li
                  className={`subscience-lesson ${
                    allLessonsCompleted ? "unlocked" : "locked"
                  }`}
                >
                  <div className="subscience-lesson-main">
                    <div>
                      <p className="subscience-lesson-number">Final Test</p>
                      <p className="subscience-lesson-title">Unit Test</p>
                      <p className="subscience-lesson-status">
                        {allLessonsCompleted ? "Unlocked" : "Complete all lessons first"}
                      </p>
                    </div>

                    <div className="subscience-lesson-tags">
                      {allLessonsCompleted ? (
                        <span className="tag tag-unlocked">Ready</span>
                      ) : (
                        <span className="tag tag-locked">Locked</span>
                      )}
                    </div>
                  </div>

                    <div className="subscience-lesson-actions">
                    <button
                      className="lesson-action-btn"
                      disabled={!allLessonsCompleted}
                      onClick={() => navigate(`/unit-test/${subId}`)}
                    >
                      Start Unit Test
                    </button>
                  </div>
                </li>
              </ul>
            </section>
          </div>
        )}
      </main>
    </div>
  );
}

export default SubscienceUnit;
